import{_ as t,H as E,f as i,i as a}from"./chunks/framework.BH2BK_3i.js";const g=JSON.parse('{"title":"06-锁：如何理解锁的同步阻塞队列与条件队列？","description":"","frontmatter":{},"headers":[{"level":2,"title":"锁的基本存储结构","slug":"锁的基本存储结构","link":"#锁的基本存储结构","children":[]},{"level":2,"title":"锁的底层实现机制 -AQS 实现原理剖析","slug":"锁的底层实现机制-aqs-实现原理剖析","link":"#锁的底层实现机制-aqs-实现原理剖析","children":[{"level":3,"title":"锁的申请","slug":"锁的申请","link":"#锁的申请","children":[]},{"level":3,"title":"锁的释放","slug":"锁的释放","link":"#锁的释放","children":[]},{"level":3,"title":"锁的条件等待队列","slug":"锁的条件等待队列","link":"#锁的条件等待队列","children":[]}]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"课后题","slug":"课后题","link":"#课后题","children":[]}],"relativePath":"中间件核心技术与实战/06-锁：如何理解锁的同步阻塞队列与条件队列？.md","filePath":"中间件核心技术与实战/06-锁：如何理解锁的同步阻塞队列与条件队列？.md","lastUpdated":1795537466000}'),n={name:"中间件核心技术与实战/06-锁：如何理解锁的同步阻塞队列与条件队列？.md"};function s(p,e,o,r,B,l){return E(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="_06-锁-如何理解锁的同步阻塞队列与条件队列" tabindex="-1">06-锁：如何理解锁的同步阻塞队列与条件队列？ <a class="header-anchor" href="#_06-锁-如何理解锁的同步阻塞队列与条件队列" aria-label="Permalink to &quot;06-锁：如何理解锁的同步阻塞队列与条件队列？&quot;">​</a></h1><p>你好，我是丁威。</p><p>这节课，我们重点介绍并发编程中的基石：锁。</p><h2 id="锁的基本存储结构" tabindex="-1">锁的基本存储结构 <a class="header-anchor" href="#锁的基本存储结构" aria-label="Permalink to &quot;锁的基本存储结构&quot;">​</a></h2><p>我们先通过一个简单的场景来感受一下锁的使用场景。一家三口在一起生活，家里只有一个卫生间，大家早上起床之后都要去厕所。这时候，一个人在卫生间，其他人就必须排队等待。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/06-%25E9%2594%2581/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/06-%25E9%2594%2581/1.png" alt=""></a></p><p>这个场景用 IT 术语可以表述为下面两点。</p><ul><li><p>洗手间作为一个资源在同一时间只能被一个人使用，它具备排他性。</p></li><li><p>一个人用完洗手间（资源）之后会归还锁，然后排队者重新开始竞争洗手间的使用权。</p></li></ul><p>我们可以对这个场景进行建模。</p><ul><li><p>资源：更准确地说是公共资源或共享资源需要被不同的操作者使用，但它不能同时被使用。</p></li><li><p>资源使用者：共享资源的使用者。</p></li><li><p>锁：用来保护资源的访问权。锁对象的归属权为共享资源，但当资源使用者向资源申请操作时，可以将锁授予资源使用者。这时候，资源使用者叫做锁的占有者，在此期间它有权操作资源。操作者不再需要操作资源之后，主动将锁归还。</p></li><li><p>排队队列：我们可以更专业地称之为阻塞队列，它可以存储需要访问资源但还没获取锁的资源使用者，其归属权通常为锁对象。</p></li></ul><p>这里我之所以强调归属权，主要是因为它可以帮助我们理解锁的基本结构和资源的关系。</p><p>那锁的结构是什么呢？我们通过上节课的课后题来理解这个问题。</p><p>上节课的第二道课后题是问你怎么用多线程实现面包厂的生产和销售。我在这里也给你写了一段示例代码：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/06-%25E9%2594%2581/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/06-%25E9%2594%2581/2.png" alt=""></a></p><p>面包仓库的职能是为面包厂存储面包，它需要提供两个基本的方法：存储面包和获取面包。面包仓库内部使用 ArrayList 来存储面包，但是因为 ArrayList 是一个线程不安全的存储容器，它不允许多个使用者同时存储数据，所以我们需要对资源进行保护。体现在代码上，我们可以通过 synchronized（资源对象）来创建一把锁，保护多线程对资源对象的串行访问。</p><p>我们结合 put 方法的流程来看一下锁的基本存储结构。</p><p>假设 t1、t2 两个生产者（线程）同时调用 Bakery 的 put 方法。那么 synchronized(breads) 在编译的时候，就会在资源 breads 对象上创建锁相关的结构，即锁对象。</p><p>t1，t2 在执行 synchronized(breads) 时，只有一个线程可以获取锁，另外一个线程需要等待，所以这里需要引入一个存储结构（通常为队列）来存储这些排队的线程，我们通常会使用阻塞队列。</p><p>首先获取到锁的线程 t1 在向仓库中存放面包之前需要先进行判断，如果存储空间足够，执行上图中的代码 step2。但是如果仓库没有足够的空间存储面包，就要执行代码 step3，调用锁对象的 wait 方法，让获得锁的线程 t1 阻塞，并且释放锁。</p><p>但是，被阻塞的 t1 和 t2 还是有所不同。因为 t1 被阻塞的原因是条件不满足，当面包仓库有额外的存储空间时，t1 就会被唤醒。所以我们还要引入一个条件队列，用来存放因条件不满足而被阻塞的线程。</p><p>t1 线程如果因为条件不满足而存储在条件等待队列，当存在剩余空间后，就能被其他线程唤醒继续执行后续的代码了。在这里是将面包存储到 ArrayList，那此时面包工厂中存储了面包，需要通知那些因为仓库中没有面包而阻塞的线程，调用锁的 notifyAll 方法唤醒在等待的线程。</p><p>线程 t1 因为存储空间不足在 step3 被阻塞，进入到条件等待队列。等到面包被卖出，仓库有足够的容量之后，t1 线程将被唤醒。</p><p>这里我想给你提个问题，t1 线程可以立马继续执行 step3 之后的代码 step4 吗？</p><p>答案是不能，它需要先去尝试竞争锁，成功获得锁之后才能开始执行 step4，否则就会进入到阻塞队列。</p><p>从上面这个过程中，我们可以归纳出锁的基本存储结构，它包括锁的持有者线程、锁的重入次数、阻塞队列和条件等待队列四个部分。</p><h2 id="锁的底层实现机制-aqs-实现原理剖析" tabindex="-1">锁的底层实现机制 -AQS 实现原理剖析 <a class="header-anchor" href="#锁的底层实现机制-aqs-实现原理剖析" aria-label="Permalink to &quot;锁的底层实现机制 -AQS 实现原理剖析&quot;">​</a></h2><p>在 Java 中使用锁通常有两种编程方式。一种是使用 JVM 虚拟机（Java 规范）层面提供的synchronized 关键字；另一种是使用 JUC 类库，也就是大名鼎鼎的AbstractQueuedSynchronizer，简称 AQS。</p><p>其中，synchronized 是在 JVM 虚拟机层面实现的，涉及很多底层知识，直接研读源码难度太大。相比较而言，JUC 并发编程遵从 JSR-166 规范，提供了锁的另外一种实现方式，也就是大家所熟知的 AQS 类库，更加常用和易学。</p><p>接下来，我会基于 JUC 框架，带你从代码层面近距离观摩锁的实现原理，掌握锁的本质。</p><p>在 JUC 框架中，ReentrantLock 对标 synchronized，它实现了可重入互斥锁的全部语义。语义主要包括两个方面：一个是 lock（申请锁）和 unlock（释放锁）；另一个是条件等待，对标Object 的 wait/notify。</p><p>我们先来看下 ReentrantLock 和 AQS 的类图：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/06-%25E9%2594%2581/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/06-%25E9%2594%2581/3.png" alt=""></a></p><p>简单介绍一下类图中各个类的含义。</p><ol><li>AbstractQueuedSynchronizer</li></ol><p>它是 AQS 体系的核心基类，使用的是类模版设计模式。这个类实现了锁的基本存储结构，定义了锁的基本行为。AQS 的内部数据结构为链表，持有链表的头尾节点，每一个节点用 Node表示，可以实现阻塞队列和条件等待队列。其中，Node prev、next 用于构建阻塞队列，而Node nextWatier 用于构建条件等待队列。</p><p>AQS 方法的修饰符也很有规律，其中，使用 protected 修饰的方法为抽象方法，通常需要子类去实现，从而实现不同特性的锁（例如互斥、共享锁、读写锁等）；而用 public 修饰的方法基本可以认为是模板方法，不建议子类直接覆盖。</p><p>AQS 还额外提供了很多有用的方法，我给你列了个表格，方便你在有需要的时候随时查看。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/06-%25E9%2594%2581/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/06-%25E9%2594%2581/4.png" alt=""></a></p><ol start="2"><li>AbstractOwnableSynchronizer</li></ol><p>它是 AQS 核心基类的父类，用于记录锁当前的持有者线程。</p><ol start="3"><li>ReentrantLock</li></ol><p>可重入互斥锁的具体实现。由于 Java 不支持多继承，所以由 ReentrantLock 继承抽象类Lock，用内部类的方式继承 AQS。所以说，ReentrantLock 在具体实现锁时基本都是委托内部类 Sync，而 Sync 又继承自 AQS。Sync 内部有两个子类，分别是 FairSync（公平锁）与NonfairSync（非公平锁）。</p><h3 id="锁的申请" tabindex="-1">锁的申请 <a class="header-anchor" href="#锁的申请" aria-label="Permalink to &quot;锁的申请&quot;">​</a></h3><p>接下来我们结合 ReentrantLock 的部分关键源码来看看怎么实现锁的申请与释放。先看锁的申请。</p><p>ReentrantLock 支持带超时时间的锁申请，具体实现方法是 tryLock，时序图如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/06-%25E9%2594%2581/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/06-%25E9%2594%2581/5.png" alt=""></a></p><p>AQS 的 tryAcquireNanos 代码如下图所示，该方法是在 AQS 中定义的。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/06-%25E9%2594%2581/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/06-%25E9%2594%2581/6.png" alt=""></a></p><p>解读一下核心要点。</p><p>如果线程的中断位标记为 true，表示应用方主动放弃锁的申请，可以直接抛出中断异常，结束锁的申请。</p><p>否则，调用 Sync 的 tryAcquire 尝试获取锁。如果返回 true，表示成功获取锁，可以直接返回；不然就调用 doAcquireNanos，进入锁等待队列。</p><p>Sync 的 tryAcquire 方法，代码如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/06-%25E9%2594%2581/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/06-%25E9%2594%2581/7.png" alt=""></a></p><p>尝试实现锁有几个要点。</p><p>首先我们要确保获取当前申请锁的线程。</p><p>我们还要获取锁的当前状态，也就是 state 值（state 字段的含义是当前锁的重入次数，如果state 为 0，表示当前锁并没有被占用）。这又包括两种情况。</p><p>情况一：如果 state 的值为 0，表示当前锁并没有被占用。根据申请锁的公平与否，会有不同的处理逻辑。</p><ul><li><p>如果是公平锁，那么我们需要判断阻塞队列中有没有其他线程在排队。如果有，公平锁此时无法竞争锁，返回 false，尝试获取锁失败。这个线程最终会调用 doAcquireNanos，进入到同步阻塞队列。</p></li><li><p>但是如果是非公平锁，则会首先和阻塞队列中的线程竞争，如果竞争成功，可以直接获取锁，如果竞争失败，则同样进入到阻塞队列。竞争锁的代码使用的是 CAS 机制，尝试更新 state 的值为 acquires，如果更新成功，则占有锁。成功占有锁之后，需要设置锁的拥有者为当前线程。</p></li></ul><p>情况二：如果 state 的值不为 0，表示锁已经被占用。我们需要判断当前线程是不是锁的持有者。如果是，则只需要更新 state 的值（ReentrantLock 支持可重入）；否则就进入阻塞队列，排队获取锁。</p><p>为什么在竞争锁时需要使用 CAS 呢？什么是 CAS 呢？</p><p>我们知道，申请锁时要先查询 state 的值，然后更新 state 的值。但这两步在多线程环境中并不是一个安全的操作。如下图所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/06-%25E9%2594%2581/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/06-%25E9%2594%2581/8.png" alt=""></a></p><p>这很容易导致 t1，t2 都获取到了锁。根本原因是这个步骤包括两个 CPU 指令，无法做到原子更新。</p><p>为了解决这个问题，操作系统提供了一个新的 CPU 指令（CAS），用它来实现“比较 - 和 - 更新”。具体的原理是在更新一个值之前，首先比较这个值是否发生了变化，如果确实发生了变化，那么就会更新失败，否则更新成功。</p><p>如果没有成功获取锁，当前申请锁的线程还会继续调用 AQS 的 doAcquireNanos：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/06-%25E9%2594%2581/9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/06-%25E9%2594%2581/9.png" alt=""></a></p><p>这是 AQS 机制中非常重要的一个方法，它的实现比较复杂。我们先来看一张流程图：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/06-%25E9%2594%2581/10.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/06-%25E9%2594%2581/10.png" alt=""></a></p><p>我们可以把这个流程归结为五步。</p><p>第一步：判断获取锁是不是已经超时，如果是，返回 false（ReentrantLock 支持锁获取超时）。</p><p>第二步：调用 addWaiter 方法把当前节点加入到阻塞队列中。</p><p>第三步：获取节点的前驱节点。</p><p>第四步：如果节点的前驱节点为头节点，再次调用 tryAcquire 方法尝试获取锁。如果成功获取锁，则将当前节点设置为 Head，表示当前它是锁的持有者。</p><p>第五步：如果当前节点不是头节点，或者没有成功获取锁，调用shouldParkAfterFailedAcquire 判断当前线程是否需要阻塞，如果需要阻塞，则调用LockSupport.parkNanos 阻塞线程。</p><p>接下来，我们对上面流程中的关键代码进行详细的解读。</p><p>先看第二步里 addWaiter 的具体实现：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/06-%25E9%2594%2581/11.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/06-%25E9%2594%2581/11.png" alt=""></a></p><p>因为 AQS 内部不管是阻塞队列还是条件等待队列都是基于链表实现的，所以入队列的实现比较容易理解，这里主要关注三点。</p><ol><li><p>需要创建一个 Node 节点，将线程对象存储在 Node 节点中，方便后续对线程进行阻塞或唤醒。</p></li><li><p>链表在多线程环境中操作并不安全，所以在更新链表相关指针时要引入 CAS 机制。首先将if 和 CAS 组合进行一次测试，如果更新成功，直接结束操作；不然就要使用 for 和 CAS 的组合进行多次重试，一直到更新成功为止。这背后的原理是，多线程在更新 Head 或者 Tail时，只有一个能更新成功，如果更新失败，则重新获取 Head 或者 Tail 再进行更新，直到节点安全地加入链表为止。</p></li><li><p>在入队的过程中，如果队列为空时，会创建一个空的 Node 节点，但是不持有任何线程信息。</p></li></ol><p>等到节点成功加入到阻塞队列后，需要判断节点的前驱节点是否为头节点，如果是，表示成功获取锁。成功获得锁的线程对应的节点将成为头节点，设置头节点的代码如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/06-%25E9%2594%2581/12.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/06-%25E9%2594%2581/12.png" alt=""></a></p><p>头节点持有的线程对象为什么为空呢？</p><p>这是因为锁的持有者被记录在了 AbstractOwnableSynchronizer 的 ThreadexclusiveOwnerThread 属性中。这样做的好处是，我们可以认为头节点是锁的持有者，但头节点却并不维护线程对象。在实现非公平锁时，如果锁被新线程抢占，不需要更新头节点。</p><p>相反，如果节点的前驱节点不是头节点，则需要判断申请锁的线程是否需要阻塞。我们可以通过 shouldParkAfterFailedAcquire 方法来实现它：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/06-%25E9%2594%2581/13.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/06-%25E9%2594%2581/13.png" alt=""></a></p><p>解读一下，如果前驱节点的状态是 Node.SIGNAL，则当前线程直接进入到阻塞队列，排队获取锁。</p><p>这里再对 Node.SIGNAL 补充说明一下：Node.SIGNAL 的含义是节点需要一个信号来唤醒自己，如果前驱节点的状态为 Node.SIGNAL，说明前驱节点在等待被唤醒，那作为前驱节点的后继节点，自然而然也需要等待被唤醒。</p><p>如果前驱节点的状态大于 0，需要删除当前节点之前连续的节点。因为当前节点的状态只有Node.CANCELLED 大于 0，所以如果前驱节点的状态大于 0 说明是已取消的节点，需要被删除。示例图如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/06-%25E9%2594%2581/14.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/06-%25E9%2594%2581/14.png" alt=""></a></p><p>这里以当前节点为基准（状态为 -1）向前删除。注意，只删除连续的 1，也就是说遇到非取消节点立即停止删除。基于分段思想，我们不会删除前面所有的已取消节点，因为删除节点的方向是从后向前的，而且 shouldParkAfterFailedAcquire 这个方法会在多个线程获取锁之后被多个线程调用，但后续的节点在执行删除时，遇到当前线程，会被切割成段，段与段之间并不会有多线程执行，从而可以安全地操作各自的段。</p><p>如果前驱节点的状态为 0 或 Propagate，需要尝试把前驱节点的状态变更为 Node.SIGNAL。也就是说，不阻塞线程，而是再次试图获取锁相关的逻辑。</p><p>如果需要阻塞线程，先判断本次获取锁的剩余时间是否大于等于 spinForTimeoutThreshold，如果是，则通过自旋方式进行循环，否则将使线程阻塞。其中 spinForTimeoutThreshold 默认为 1s，这样做的目的主要是如果本次锁申请距超时还剩不到 1s，就没有必要再阻塞线程了，避免线程切换带来的额外开销。</p><p>如果需要阻塞线程，我们可以调用 LockSupport.parkNanos 方法使线程阻塞，这个方法同样支持设置超时时间。</p><h3 id="锁的释放" tabindex="-1">锁的释放 <a class="header-anchor" href="#锁的释放" aria-label="Permalink to &quot;锁的释放&quot;">​</a></h3><p>申请完锁之后，我们还会面临锁的释放。我们可以通过 ReentrantLock 的 unlock 方法释放锁，并最终调用 AQS 的模版方法：release 方法，代码如图所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/06-%25E9%2594%2581/15.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/06-%25E9%2594%2581/15.png" alt=""></a></p><p>在详细地介绍具体的方法之前，我们先来看一张整体的时序图，理解一下释放锁的实现机制。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/06-%25E9%2594%2581/16.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/06-%25E9%2594%2581/16.png" alt=""></a></p><p>锁的释放主要包含如下几个步骤：</p><p>第一步：释放锁，必须先判断当前线程是否是锁的持有者，如果不是，抛出IllegalMonitorStateException 异常。</p><p>第二步：判断锁的剩余占有次数，如果为 0，表示锁已释放，需要唤醒阻塞队列中的其他排队线程。</p><p>我们看一下释放锁的关键代码。具体定义在 ReentrantLock$Sync 的 tryRelease 中：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/06-%25E9%2594%2581/17.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/06-%25E9%2594%2581/17.png" alt=""></a></p><p>这段代码有两个要点。</p><ul><li><p>如果当前锁的占有者不是申请释放锁的线程，那就不能释放锁，只有持有者线程才能释放锁。这个时候需要抛出监视器错误。</p></li><li><p>如果一个锁被同一个线程重入 n 次，那对应也要释放 n 次。当持有次数为 0 时，表示可以释放锁。</p></li></ul><p>尝试释放锁后，返回“成功”，接下来要做的是唤醒阻塞队列中的下一个线程。当然，如果你使用的是非公平锁，新来的线程在这个时候是可以直接获取锁的，这样唤醒的线程如果没能获取锁，就又会进入到阻塞队列中。</p><p>从阻塞队列中查找下一个待唤醒的线程需要使用 AQS 的 unparkSuccessor 方法，代码如下图所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/06-%25E9%2594%2581/18.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/06-%25E9%2594%2581/18.png" alt=""></a></p><p>这个过程主要包括四个要点，分别对应上图的 step1、step2、step3 和 step4。</p><p>step1：因为这个方法的参数是头节点，头节点是当前锁的持有者，所以在释放锁时，我们要找头节点的下一个未取消的节点。</p><p>step2：确认头节点的状态。如果头节点的状态不为 0，则更新为 0。</p><p>step3：从链表的尾部开始寻找，找到头节点后面的第一个非取消节点。这里说明一下，因为我们在维护节点的前驱节点时使用了 CAS，通过前驱节点遍历是可靠的，不会遗漏节点。</p><p>step4：找到对应的节点，调用 LockSupport.unpark 方法唤醒线程。线程被唤醒后会继续去竞争锁。这里唤醒的是申请锁时用 LockSupport.park 阻塞的线程，因为这样可以让锁的申请和释放形成闭环通道。</p><h3 id="锁的条件等待队列" tabindex="-1">锁的条件等待队列 <a class="header-anchor" href="#锁的条件等待队列" aria-label="Permalink to &quot;锁的条件等待队列&quot;">​</a></h3><p>理解了锁的申请和释放，接下来我们再来看看 ReentrantLock 是怎么实现 Object.wait 和Object.notify 语义的，这是线程之间协作的基石。</p><p>线程调用锁对象的 wait 方法时会进入到条件等待队列，而线程调用锁对象的 notify 方法，会唤醒条件队列中的一个线程，具有下面三个特征。</p><ol><li><p>Object 的 wait 与 notify 必须在临界区中调用。</p></li><li><p>Object 的 wait 和 notify 的使用场景为条件等待。例如，一个线程获取锁后，需要等待某一个条件满足后才能继续执行。这时，为了节省 CPU 资源，线程可以调用锁的 wait 方法使自己阻塞，等待条件满足后被别的线程唤醒。</p></li><li><p>Object 的 wait 方法会释放当前锁。</p></li></ol><p>在 AQS 中，实现 Object 的 notify 和 wait 功能的主要类为 Condition，类图如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/06-%25E9%2594%2581/19.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/06-%25E9%2594%2581/19.png" alt=""></a></p><p>Condition 的接口对标 Object 的 wait 与 notify 方法，底层的存储结构为一个链表（条件阻塞队列）。链表中的节点为 Node，条件阻塞队列为单链表，链表通过 Node nextWaiter 指针维护链表。</p><p>因为前面在介绍 lock 语义的时候我们用的是带超时时间的方法，所以为了覆盖更多的 AQS 方法，这里我们就变一变，用不带超时时间的方法来解读 await 语言。不过这两者在本质上并没有差别。</p><p>为了帮助你更快掌控 await 的整体实现思路，可以先看一下时序图：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/06-%25E9%2594%2581/20.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/06-%25E9%2594%2581/20.png" alt=""></a></p><p>Condition 的 wait() 方法对标 Object.wait()，我们来看一下它的具体实现逻辑：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/06-%25E9%2594%2581/21.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/06-%25E9%2594%2581/21.png" alt=""></a></p><p>我们结合 Object.wait 的语义来体会一下 await 方法中最关键的六个步骤。</p><p>step1：如果当前线程被中断，要直接抛出中断异常。</p><p>step2：将节点加入条件等待队列中。</p><p>step3：释放锁，并保存释放之前锁的状态，等到条件满足线程被唤醒后，需要重新申请指定数量的锁。</p><p>step4：如果节点存在于条件队列而不在阻塞队列中，说明未收到 signal 信号，线程会被阻塞；如果线程被中断，就结束条件队列的等待。</p><p>step5：再次尝试申请锁，并检查唤醒的原因，看看是因为收到 signal 信号而被唤醒，还是因为收到了中断信号。</p><p>step6：如果先收到 signal 信号，再收到中断信号，那就要重新设置线程中断位，等待下一次中断检查点；如果是先收到中断信号，后收到 signal 信号，就直接抛出中断异常；如果正常收到 signal 信号，await 方法结束阻塞，则继续执行后续逻辑。</p><p>其中，第二步中的加入条件队列，具体的代码实现是将节点接入到链表的尾部，如果有取消的节点就把它删除。这里线程是安全的，因为执行 await 方法的前提条件是要获取锁。</p><p>第四步是用 await 方法阻塞和唤醒线程的关键。核心代码如下图所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/06-%25E9%2594%2581/22.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/06-%25E9%2594%2581/22.png" alt=""></a></p><p>我们来看一下怎么判断线程是否在同步队列中（用 isOnSyncQueue 方法实现）。</p><ul><li><p>如果节点的状态为 Node.CONDITION，或者 node.prev 为空，表示线程在等待条件被触发。为什么节点的前驱节点不为空就可以认为线程在同步阻塞队列中呢？这是因为进入同步队列时是用 CAS 机制来更新前驱节点的。</p></li><li><p>如果 Node 的 next 指针不为空，表示线程在同步阻塞队列中，返回 true。</p></li><li><p>如果不满足上述条件，则从尾部节点再查找一遍，如果能找到，返回 true，否则返回false。</p></li></ul><p>因为节点如果在条件等待队列中，说明条件不满足，线程需要阻塞并等待条件触发。线程可以通过下面几种方式被唤醒：</p><ul><li><p>由于正常收到 signal 信号被唤醒；</p></li><li><p>先收到 signal 信号，然后收到中断信号；</p></li><li><p>先收到中断信号，再收到 signal 信号。</p></li></ul><p>那怎么判断唤醒方式呢？</p><p>我们可以通过 checkInterruptWhileWaiting 来实现它。也就是检测线程的中断标志位，如果线程并没有设置中断位，则返回 0。如果检测到了中断位，则用 transferAfterCancelledWait 方法来判断中断信号和 signal 的先后顺序。</p><p>transferAfterCancelledWait 的核心实现逻辑是，如果成功将节点的状态从 Node.CONDITION更新为 0，就表示先收到了中断标记，否则就是先收到了 signal 信号。因为如果是先收到signal 信号，节点的状态应该是 NODE.SIGNAL，而且节点会进入同步阻塞队列。这样做可以有效避免 signal 信号丢失。</p><p>线程被唤醒后需要重新申请锁，调用 acquireQueued 方法来实现，这一步和前面我们提到的申请流程类似，这里就不再重复了。</p><p>当条件满足后，线程被唤醒，这时候我们就要用到 Condition 的 signal() 方法了。signal 方法的时序图如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/06-%25E9%2594%2581/23.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/06-%25E9%2594%2581/23.png" alt=""></a></p><p>这部分就是从条件队列中找到第一个没有取消的节点，然后唤醒它。实现 transferForSignal方法的具体代码如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/06-%25E9%2594%2581/24.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/06-%25E9%2594%2581/24.png" alt=""></a></p><p>这个方法有三个要点。</p><p>第一，要使用 CAS 尝试将节点状态从 CONDITION 转化为 0。如果更新失败，说明节点已取消，需要返回 false，继续通知下一个等待线程。</p><p>第二，将线程从条件阻塞队列放入到同步阻塞队列，这一步非常关键，可以防止 signal 信号丢失。</p><p>第三，如果线程加入同步队列后，其前置节点的状态为已取消，或者将其设置为 signal 失败，则直接唤醒线程。</p><p>signal 方法内部的实现机制就是确保线程要么在同步队列中，要么在条件等待队列中。这样可以有效防止通知信号丢失，避免线程一直被阻塞。</p><p>到这里，Condition 的 await 和 signal 方法就都介绍完了。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>这节课，我们首先通过一个简单的生活场景，并结合生产者 - 消费者模型引出了锁的基本结构，它包括：锁要保护的资源、锁的拥有者、同步阻塞队列和条件等待队列。</p><p>紧接着，我们以源码分析为主要手段，辅助流程图、时序图，一步一步地实现了锁的申请和释放。</p><p>同步阻塞队列存放的都是竞争锁失败的线程，主要表征的是线程之间的竞争、互斥，而条件等待队列中存储的是因为某一个条件不满足而需要阻塞的线程，通常需要被其他线程主动唤醒，主要表征的是线程协作。</p><p>我们可以使用 LockSupport.parkNanos 来阻塞线程，并通过 LockSupport.unpark 方法来唤醒线程。</p><p>如果你对中间件感兴趣，对锁的语义的理解必不可少。它虽然有一定难度，但是只要攻下了源码，读懂 AQS，对锁的理解与认知能力会有一个质的提升，对多线程协作开发大有裨益。</p><p>JUC 的体系非常庞大，这节课不能全面覆盖，但是只要掌握了 AQS，后面再去学习CountDownLatch、信号量、CAS 等知识会变得非常容易。如果你有兴趣，也可以读一读我写过的和锁相关的文章：《锁的优化思路》和《disruptor 无锁化设计实践》，应该可以给你更多的启发。</p><h2 id="课后题" tabindex="-1">课后题 <a class="header-anchor" href="#课后题" aria-label="Permalink to &quot;课后题&quot;">​</a></h2><p>最后，还是给你留一道课后题。</p><p>请你尝试写一篇文章，分析 JUC 读写锁的源码，重点剖析读锁的申请与释放还有写锁的申请与释放。我也给你提供一篇文章供你参考：《Java 并发锁 ReentrantReadWriteLock 读写锁源码分析》。</p><p>关于这节课，如果你还有不理解的问题，也欢迎你在留言区留言。我们下节课再见！</p>',164)])])}const h=t(n,[["render",s]]);export{g as __pageData,h as default};
